const req = $input.first().json;
const FREE_EMAIL = ["gmail.com", "yahoo.com", "outlook.com", "hotmail.com", "icloud.com", "proton.me", "protonmail.com", "aol.com", "live.com", "msn.com", "gmx.com", "mail.com", "yandex.com", "qq.com", "163.com"];

function parseJson(raw, fallback) {
  if (raw && typeof raw === "object") { return raw; }
  if (typeof raw === "string" && raw.trim()) {
    try { return JSON.parse(raw); } catch (e) { return fallback; }
  }
  return fallback;
}
function fnv(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(16).padStart(8, "0");
}

const lead = parseJson(req.lead, {});
const ICP_DEFAULT = {
  target_size_bands: ["51-200", "201-1000", "1000+"],
  core_use_cases: ["workflow automation", "ai agents", "internal tooling"],
  min_score_for_outreach: 50
};
const icp = parseJson(req.icp, ICP_DEFAULT);
if (!Array.isArray(icp.target_size_bands) || !icp.target_size_bands.length) { icp.target_size_bands = ICP_DEFAULT.target_size_bands; }
if (!Array.isArray(icp.core_use_cases) || !icp.core_use_cases.length) { icp.core_use_cases = ICP_DEFAULT.core_use_cases; }
if (typeof icp.min_score_for_outreach !== "number") { icp.min_score_for_outreach = ICP_DEFAULT.min_score_for_outreach; }

const email = String(lead.email || "").trim().toLowerCase();
const emailDomain = email.indexOf("@") > 0 ? email.split("@")[1] : "";
const freeEmail = FREE_EMAIL.indexOf(emailDomain) !== -1;
const rawSite = String(lead.website || lead.company_domain || "").trim();
const siteDomain = rawSite
  ? rawSite.replace(/^https?:\/\//i, "").replace(/^www\./i, "").split("/")[0].toLowerCase()
  : "";
const companyDomain = siteDomain || (freeEmail ? "" : emailDomain);

const FIELDS = ["first_name", "last_name", "job_title", "company_name", "company_size", "phone", "country", "source", "message", "budget", "timeline", "use_case"];
const lines = [];
if (email) { lines.push("email: " + email); }
FIELDS.forEach(function (f) {
  if (lead[f] !== undefined && lead[f] !== null && String(lead[f]).trim()) { lines.push(f + ": " + String(lead[f]).trim()); }
});
if (companyDomain) { lines.push("company_domain: " + companyDomain); }
const leadBlock = lines.join("\n");

const rawTenant = String(req.tenant_id || "default").trim().toLowerCase();
const tenantId = /^[a-z0-9][a-z0-9_-]{0,62}$/.test(rawTenant) ? rawTenant : "";

const errors = [];
if (!tenantId) { errors.push("tenant_id must match ^[a-z0-9][a-z0-9_-]{0,62}$; got " + JSON.stringify(rawTenant)); }
if (!email) { errors.push("lead.email is required"); }
else if (!/^[^@\s]+@[^@\s.]+\.[^@\s]+$/.test(email)) { errors.push("lead.email is not a valid address: " + email); }
if (!leadBlock) { errors.push("the lead carries no readable fields to qualify"); }

const leadKey = email || ("anon-" + fnv(JSON.stringify(lead)));
const enrich = String(req.enrich === undefined || req.enrich === null || req.enrich === "" ? "false" : req.enrich).toLowerCase() === "true";

return [{ json: {
  lead: lead,
  lead_key: leadKey,
  email: email,
  email_domain: emailDomain,
  free_email: freeEmail,
  company_domain: companyDomain,
  company_url: companyDomain ? "https://" + companyDomain : "",
  lead_block: leadBlock,
  icp: icp,
  icp_block: JSON.stringify(icp, null, 2),
  enrich: enrich && !!companyDomain,
  enrich_skipped_reason: enrich && !companyDomain ? "no company domain could be derived from the lead" : (enrich ? "" : "enrichment not requested"),
  signals_override: String(req.signals_override || ""),
  rubric_override: String(req.rubric_override || ""),
  verification_mode: String(req.verification_mode || "deterministic_only"),
  tenant_id: tenantId,
  trace_id: String(req.trace_id || "").trim().slice(0, 64),
  source_workflow: String(req.source_workflow || "unknown"),
  valid: errors.length === 0,
  validation_errors: errors,
  started_at_ms: Date.now()
} }];

const req = $("Normalise Lead").first().json;
let signals = {};
let error = "";
try { signals = JSON.parse(req.signals_override); }
catch (e) { error = "signals_override is not valid JSON: " + e.message; }
return [{ json: {
  signals: signals,
  signals_source: "supplied",
  signals_raw: req.signals_override,
  model_provider: null,
  model_latency_ms: 0,
  prompt_sha: null,
  parse_error: error
} }];

const req = $("Normalise Lead").first().json;
const incoming = $input.first().json;
const icp = req.icp;

// ---- The rubric is data, not code -----------------------------------------
// Keeping it as a value means a candidate rubric can be backtested against the
// same leads through this same workflow, and an offline evaluator never has to
// reimplement the scoring and drift away from it.
const DEFAULT_RUBRIC = {
  version: "1.2.0",
  seniority: { executive: 12, vp: 11, director: 9, manager: 6, ic: 2, unknown: 0 },
  authority: { decision_maker: 13, influencer: 8, end_user: 3, unknown: 0 },
  budget: { explicit: 20, implied: 12, none: 2, unknown: 0 },
  timeline: { immediate: 15, this_quarter: 12, this_year: 6, no_timeline: 2, unknown: 0 },
  pain: { specific: 10, general: 5, none: 0, unknown: 0 },
  fit: { core: 10, adjacent: 6, out_of_scope: 0, unknown: 0 },
  size_points: { in_target: 20, adjacent: 12, outside: 4, unknown: 0 },
  modifiers: { competitor_mentioned: 4, consumer_email_domain: -8, unsupported_evidence: -10, signal_parse_failure: -15 },
  caps: { unknown_threshold: 4, unknown_cap: 45, out_of_scope_cap: 15, parse_error_cap: 40, unreadable_cap: 45 },
  tiers: { hot: 75, warm: 50, cold: 25 }
};

let R = DEFAULT_RUBRIC;
let rubricSource = "default";
let rubricError = "";
if (req.rubric_override) {
  try {
    const candidate = JSON.parse(req.rubric_override);
    const REQUIRED = ["seniority", "authority", "budget", "timeline", "pain", "fit", "size_points", "modifiers", "caps", "tiers"];
    const missing = REQUIRED.filter(function (k) { return !candidate || typeof candidate[k] !== "object"; });
    if (missing.length) {
      rubricError = "rubric_override is missing required section(s): " + missing.join(", ");
    } else {
      R = candidate;
      R.version = String(candidate.version || "candidate-unversioned");
      rubricSource = "override";
    }
  } catch (e) {
    rubricError = "rubric_override is not valid JSON: " + e.message;
  }
}

// ---- Canonicalise the model's labels ------------------------------------
const ALIASES = {
  seniority: { c_level: "executive", c_suite: "executive", cxo: "executive", founder: "executive", owner: "executive", chief: "executive", vice_president: "vp", svp: "vp", evp: "vp", head: "director", head_of: "director", lead: "manager", individual_contributor: "ic", engineer: "ic", staff: "ic" },
  decision_authority: { decision: "decision_maker", buyer: "decision_maker", economic_buyer: "decision_maker", evaluator: "influencer", recommender: "influencer", champion: "influencer", user: "end_user" },
  budget_signal: { stated: "explicit", confirmed: "explicit", approved: "explicit", inferred: "implied", implicit: "implied", no_budget: "none" },
  timeline: { asap: "immediate", urgent: "immediate", now: "immediate", next_quarter: "this_quarter", quarter: "this_quarter", year: "this_year", none: "no_timeline", no: "no_timeline" },
  pain_specificity: { detailed: "specific", concrete: "specific", vague: "general", broad: "general" },
  use_case_fit: { direct: "core", primary: "core", near: "adjacent", related: "adjacent", unrelated: "out_of_scope", off: "out_of_scope" }
};
const BANDS = ["1-10", "11-50", "51-200", "201-1000", "1000+"];

function slug(v) {
  return String(v == null ? "" : v).trim().toLowerCase().replace(/[^a-z0-9+\-]+/g, "_").replace(/^_+|_+$/g, "");
}
function bandFromCount(n) {
  if (n <= 10) { return "1-10"; }
  if (n <= 50) { return "11-50"; }
  if (n <= 200) { return "51-200"; }
  if (n <= 1000) { return "201-1000"; }
  return "1000+";
}
function canonBand(raw) {
  const t = String(raw == null ? "" : raw).trim().toLowerCase();
  const compact = t.replace(/\s+/g, "").replace(/employees?/g, "").replace(/people/g, "").replace(/staff/g, "").replace(/,/g, "");
  if (BANDS.indexOf(compact) !== -1) { return compact; }
  const range = compact.match(/^(\d+)[-–](\d+)$/);
  if (range) { return bandFromCount(Number(range[2])); }
  const plus = compact.match(/^(\d+)\+$/);
  if (plus) { return bandFromCount(Number(plus[1]) + 1); }
  const single = compact.match(/^(\d+)$/);
  if (single) { return bandFromCount(Number(single[1])); }
  return compact ? compact : "unknown";
}

const original = incoming.signals || {};
const s = JSON.parse(JSON.stringify(original));
const ENUM_FIELDS = ["seniority", "decision_authority", "budget_signal", "timeline", "pain_specificity", "use_case_fit"];
const renamed = [];
ENUM_FIELDS.forEach(function (f) {
  const before = original[f];
  if (before === undefined || before === null) { s[f] = "unknown"; return; }
  const slugged = slug(before);
  const mapped = (ALIASES[f] && ALIASES[f][slugged]) || slugged;
  s[f] = mapped || "unknown";
  if (s[f] !== String(before)) { renamed.push({ field: f, from: String(before), to: s[f] }); }
});
const bandBefore = original.company_size_band;
s.company_size_band = canonBand(bandBefore);
if (bandBefore !== undefined && s.company_size_band !== String(bandBefore)) { renamed.push({ field: "company_size_band", from: String(bandBefore), to: s.company_size_band }); }

// ---- Rubric ---------------------------------------------------------------
function pick(map, value) {
  const key = String(value || "unknown");
  return (map && typeof map[key] === "number") ? map[key] : 0;
}

const components = [];
const seniorityPts = pick(R.seniority, s.seniority);
const authorityPts = pick(R.authority, s.decision_authority);
const authorityMax = (R.seniority.executive || 0) + (R.authority.decision_maker || 0);
components.push({ component: "authority", points: seniorityPts + authorityPts, max: authorityMax, detail: "seniority=" + String(s.seniority || "unknown") + " (" + seniorityPts + "), decision_authority=" + String(s.decision_authority || "unknown") + " (" + authorityPts + ")" });

const band = String(s.company_size_band || "unknown");
const bandIdx = BANDS.indexOf(band);
let sizePts = pick(R.size_points, "unknown");
let sizeDetail = "company_size_band=" + band + " could not be read as a band";
if (bandIdx !== -1) {
  const targets = icp.target_size_bands.map(function (b) { return BANDS.indexOf(b); }).filter(function (i) { return i !== -1; });
  const inTarget = targets.indexOf(bandIdx) !== -1;
  const adjacent = targets.some(function (t) { return Math.abs(t - bandIdx) === 1; });
  sizePts = inTarget ? R.size_points.in_target : (adjacent ? R.size_points.adjacent : R.size_points.outside);
  sizeDetail = "company_size_band=" + band + (inTarget ? " is inside the ICP bands" : (adjacent ? " is one band outside the ICP" : " is well outside the ICP"));
}
components.push({ component: "company_size_fit", points: sizePts, max: R.size_points.in_target, detail: sizeDetail });

components.push({ component: "budget", points: pick(R.budget, s.budget_signal), max: R.budget.explicit, detail: "budget_signal=" + String(s.budget_signal || "unknown") });
components.push({ component: "timeline", points: pick(R.timeline, s.timeline), max: R.timeline.immediate, detail: "timeline=" + String(s.timeline || "unknown") });
components.push({ component: "pain", points: pick(R.pain, s.pain_specificity), max: R.pain.specific, detail: "pain_specificity=" + String(s.pain_specificity || "unknown") });
components.push({ component: "use_case_fit", points: pick(R.fit, s.use_case_fit), max: R.fit.core, detail: "use_case_fit=" + String(s.use_case_fit || "unknown") });

const base = components.reduce(function (a, c) { return a + c.points; }, 0);
const maxPossible = components.reduce(function (a, c) { return a + (c.max || 0); }, 0);

// ---- Evidence grounding ---------------------------------------------------
let enrichmentText = "";
try { enrichmentText = String($("Capture Enrichment").first().json.enrichment_text || ""); } catch (e) { }
const haystack = (req.lead_block + "\n" + enrichmentText).toLowerCase();
const evidence = Array.isArray(s.evidence) ? s.evidence : [];
const unsupported = [];
evidence.forEach(function (e) {
  const quote = String((e && e.quote) || "").trim();
  if (!quote) { return; }
  if (haystack.indexOf(quote.toLowerCase()) === -1) { unsupported.push({ signal: (e && e.signal) || "unknown", quote: quote.slice(0, 200) }); }
});

const ENUMS = ["seniority", "decision_authority", "company_size_band", "budget_signal", "timeline", "use_case_fit"];
const unknownCount = ENUMS.filter(function (k) { return String(s[k] || "unknown") === "unknown"; }).length;
const MAPS = { seniority: R.seniority, decision_authority: R.authority, budget_signal: R.budget, timeline: R.timeline, use_case_fit: R.fit };
const unreadable = ENUMS.filter(function (k) {
  const v = String(s[k] || "unknown");
  if (v === "unknown") { return false; }
  if (k === "company_size_band") { return BANDS.indexOf(v) === -1; }
  return typeof MAPS[k][v] !== "number";
});

const modifiers = [];
if (s.competitor_mentioned === true) { modifiers.push({ modifier: "competitor_mentioned", points: R.modifiers.competitor_mentioned, reason: "an active evaluation is in progress" }); }
if (req.free_email) { modifiers.push({ modifier: "consumer_email_domain", points: R.modifiers.consumer_email_domain, reason: "the lead used a free email provider rather than a company address" }); }
if (unsupported.length) { modifiers.push({ modifier: "unsupported_evidence", points: R.modifiers.unsupported_evidence, reason: unsupported.length + " quoted piece(s) of evidence do not appear in the lead or the enrichment" }); }
if (incoming.parse_error) { modifiers.push({ modifier: "signal_parse_failure", points: R.modifiers.signal_parse_failure, reason: incoming.parse_error }); }

const modifierTotal = modifiers.reduce(function (a, m) { return a + m.points; }, 0);

// Normalised to 100 so a candidate rubric with different weights stays
// comparable against the production one.
const rawScore = base + modifierTotal;
let score = maxPossible > 0 ? Math.round((rawScore / maxPossible) * 100) : 0;
score = Math.max(0, Math.min(100, score));

const caps = [];
if (unknownCount >= R.caps.unknown_threshold) { caps.push({ cap: R.caps.unknown_cap, reason: unknownCount + " of " + ENUMS.length + " signals are unknown, so the lead is too thin to rank highly" }); }
if (String(s.use_case_fit) === "out_of_scope") { caps.push({ cap: R.caps.out_of_scope_cap, reason: "the stated use case is outside the ICP" }); }
if (incoming.parse_error) { caps.push({ cap: R.caps.parse_error_cap, reason: "the signals could not be parsed, so the score is not trustworthy" }); }
if (unreadable.length) { caps.push({ cap: R.caps.unreadable_cap, reason: unreadable.length + " signal(s) came back outside the agreed value set: " + unreadable.join(", ") }); }
caps.forEach(function (c) { if (score > c.cap) { score = c.cap; } });

const disqualified = String(s.use_case_fit) === "out_of_scope";
let tier = "DISQUALIFIED";
if (!disqualified) {
  if (score >= R.tiers.hot) { tier = "HOT"; }
  else if (score >= R.tiers.warm) { tier = "WARM"; }
  else if (score >= R.tiers.cold) { tier = "COLD"; }
}

const confidence = Math.round((1 - ((unknownCount + unreadable.length) / ENUMS.length)) * 100) / 100;

return [{ json: {
  signals: s,
  signals_original: original,
  canonicalised: renamed,
  unreadable_signals: unreadable,
  signals_source: incoming.signals_source,
  signals_raw: incoming.signals_raw,
  model_provider: incoming.model_provider,
  model_latency_ms: incoming.model_latency_ms,
  prompt_sha: incoming.prompt_sha,
  parse_error: incoming.parse_error,
  score: score,
  base_score: base,
  max_possible: maxPossible,
  tier: tier,
  confidence: Math.max(0, confidence),
  unknown_signals: unknownCount,
  components: components,
  modifiers: modifiers,
  caps_applied: caps,
  unsupported_evidence: unsupported,
  evidence_checked: evidence.length,
  enrichment_used: enrichmentText.length > 0,
  rubric_version: R.version,
  rubric_source: rubricSource,
  rubric_error: rubricError
} }];

const raw = $input.first().json || {};
const data = raw.data || raw;
const text = String(data.markdown || data.summary || data.content || data.html || "").trim();
const failed = !!raw.error || !text;
return [{ json: {
  enrichment_text: failed ? "" : text.slice(0, 6000),
  enrichment_source: failed ? "none" : "firecrawl",
  enrichment_url: $("Normalise Lead").first().json.company_url,
  enrichment_error: raw.error ? String(raw.error.message || raw.error) : (text ? "" : "the scrape returned no readable text"),
  enrichment_block: failed ? "(no enrichment: " + (raw.error ? String(raw.error.message || raw.error) : "the scrape returned no readable text") + ")" : text.slice(0, 6000)
} }];

const req = $("Normalise Lead").first().json;
return [{ json: {
  enrichment_text: "",
  enrichment_source: "none",
  enrichment_url: "",
  enrichment_error: "",
  enrichment_block: "(no enrichment: " + (req.enrich_skipped_reason || "enrichment not requested") + ")"
} }];

const raw = $input.first().json;
const res = (raw && raw.json) ? raw.json : raw;
let promptSha = null;
try { const p = $("Get Qualifier Prompt (08)").first().json; promptSha = (p.json ? p.json.sha : p.sha) || null; } catch (e) { }

const text = String(res.output || "").trim();
let signals = {};
let parseError = "";

const unfenced = text.replace(/^```[a-z]*\s*/i, "").replace(/```\s*$/, "").trim();
const start = unfenced.indexOf("{");
const end = unfenced.lastIndexOf("}");
const candidate = (start !== -1 && end > start) ? unfenced.slice(start, end + 1) : unfenced;
try { signals = JSON.parse(candidate); }
catch (e) { parseError = "model output was not parseable JSON: " + e.message; }
if (!signals || typeof signals !== "object") { signals = {}; }

return [{ json: {
  signals: signals,
  signals_source: "model",
  signals_raw: text.slice(0, 4000),
  model_provider: res.selected_provider || null,
  model_latency_ms: Number(res.latency_ms || 0),
  model_cost_usd: Number(res.estimated_cost_usd || 0),
  prompt_sha: promptSha,
  parse_error: parseError
} }];

const req = $("Normalise Lead").first().json;
const scored = $("Score Against Rubric").first().json;
const raw = $input.first().json;
const v = (raw && raw.json) ? raw.json : raw;

const schemaClean = v.verified === true;
const fabricated = (scored.unsupported_evidence || []).length > 0;
const unreadable = (scored.unreadable_signals || []).length > 0;
const thin = scored.confidence < 0.5;

const reviewReasons = [];
if (!schemaClean) { reviewReasons.push("the extracted signals failed verification (" + ((v.issues || []).length) + " issue(s))"); }
if (fabricated) { reviewReasons.push(scored.unsupported_evidence.length + " quoted piece(s) of evidence are not present in the source text"); }
if (unreadable) { reviewReasons.push("signals outside the agreed value set: " + scored.unreadable_signals.join(", ")); }
if (scored.tier === "HOT" && thin) { reviewReasons.push("a HOT tier on confidence " + scored.confidence + " is not safe to act on unreviewed"); }
if (scored.parse_error) { reviewReasons.push(scored.parse_error); }
if (scored.rubric_error) { reviewReasons.push(scored.rubric_error + " - production rubric " + scored.rubric_version + " was used instead"); }

let action = "discard";
if (scored.tier === "HOT") { action = "route_to_sales"; }
else if (scored.tier === "WARM") { action = "nurture"; }
else if (scored.tier === "COLD") { action = "hold"; }
if (reviewReasons.length && action === "route_to_sales") { action = "route_to_sales_after_review"; }

const outreachAllowed = scored.score >= req.icp.min_score_for_outreach && scored.tier !== "DISQUALIFIED" && !fabricated && !unreadable;

return [{ json: {
  lead_key: req.lead_key,
  email: req.email,
  company_domain: req.company_domain,
  tenant_id: req.tenant_id,
  trace_id: req.trace_id,
  score: scored.score,
  tier: scored.tier,
  confidence: scored.confidence,
  recommended_action: action,
  outreach_allowed: outreachAllowed,
  outreach_block_reason: outreachAllowed ? "" : (fabricated ? "unsupported evidence" : (unreadable ? "signals outside the agreed value set" : (scored.tier === "DISQUALIFIED" ? "disqualified" : "score " + scored.score + " is below the ICP outreach floor of " + req.icp.min_score_for_outreach))),
  requires_human_review: reviewReasons.length > 0,
  review_reasons: reviewReasons,
  signals: scored.signals,
  scoring: {
    rubric_version: scored.rubric_version,
    rubric_source: scored.rubric_source,
    rubric_error: scored.rubric_error,
    base_score: scored.base_score,
    max_possible: scored.max_possible,
    components: scored.components,
    modifiers: scored.modifiers,
    caps_applied: scored.caps_applied,
    unknown_signals: scored.unknown_signals,
    unreadable_signals: scored.unreadable_signals,
    canonicalised: scored.canonicalised
  },
  grounding: {
    evidence_checked: scored.evidence_checked,
    unsupported_evidence: scored.unsupported_evidence,
    enrichment_used: scored.enrichment_used
  },
  verification: {
    verified: v.verified === true,
    score: v.score === undefined ? null : v.score,
    mode: v.mode || req.verification_mode,
    issues: v.issues || []
  },
  provenance: {
    signals_source: scored.signals_source,
    model_provider: scored.model_provider,
    prompt_sha: scored.prompt_sha,
    source_workflow: req.source_workflow,
    execution_id: $execution.id
  },
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

// Q01-Q08 supply signals directly, so the rubric is the only thing under test
// and every expected score is an exact number. Q09 runs the real model.
// Q10-Q11 exercise rubric overrides.
function sig(o) {
  const base = { seniority: "unknown", decision_authority: "unknown", company_size_band: "unknown", budget_signal: "unknown", timeline: "unknown", pain_specificity: "unknown", use_case_fit: "unknown", competitor_mentioned: false, evidence: [], notes: "fixture" };
  return JSON.stringify(Object.assign(base, o));
}

const HOT_LEAD = { email: "ada@analytical.io", first_name: "Ada", last_name: "Lovelace", job_title: "VP of Engineering", company_name: "Analytical Engines", message: "We have 30k set aside and need this live this month." };
const HOT_SIGNALS = { seniority: "executive", decision_authority: "decision_maker", company_size_band: "201-1000", budget_signal: "explicit", timeline: "immediate", pain_specificity: "specific", use_case_fit: "core", evidence: [{ signal: "budget_signal", quote: "We have 30k set aside" }] };
const WARM_LEAD = { email: "sam@midco.io", job_title: "Ops Manager", message: "Looking to automate onboarding this quarter." };
const WARM_SIGNALS = { seniority: "manager", decision_authority: "influencer", company_size_band: "51-200", budget_signal: "implied", timeline: "this_quarter", pain_specificity: "general", use_case_fit: "adjacent" };

// A candidate rubric that only moves the tier thresholds. The score must not
// move; the tier must. That separation is the whole point of versioning it.
const CANDIDATE_RUBRIC = JSON.stringify({
  version: "2.0.0-candidate",
  seniority: { executive: 12, vp: 11, director: 9, manager: 6, ic: 2, unknown: 0 },
  authority: { decision_maker: 13, influencer: 8, end_user: 3, unknown: 0 },
  budget: { explicit: 20, implied: 12, none: 2, unknown: 0 },
