    checks.push({ name: "signals_from_model", pass: r.signals_source === "model", expected: "model", actual: r.signals_source });
    checks.push({ name: "provider_recorded", pass: !!r.model_provider, expected: "a provider name", actual: r.model_provider });
    checks.push({ name: "labels_readable", pass: (r.unreadable_signals || []).length === 0, expected: "every label inside the agreed value set", actual: r.unreadable_signals });
  } else {
    checks.push({ name: "score", pass: r.actual_score === r.expect_score, expected: r.expect_score, actual: r.actual_score });
    checks.push({ name: "tier", pass: r.actual_tier === r.expect_tier, expected: r.expect_tier, actual: r.actual_tier });
    checks.push({ name: "recommended_action", pass: r.actual_action === r.expect_action, expected: r.expect_action, actual: r.actual_action });
    checks.push({ name: "outreach_allowed", pass: r.actual_outreach === r.expect_outreach, expected: r.expect_outreach, actual: r.actual_outreach });
    checks.push({ name: "requires_human_review", pass: r.actual_review === r.expect_review, expected: r.expect_review, actual: r.actual_review });
    if (r.expect_modifier) {
      checks.push({ name: "modifier_applied", pass: (r.modifiers || []).indexOf(r.expect_modifier) !== -1, expected: r.expect_modifier, actual: r.modifiers });
    }
  }
  if (r.expect_rubric) {
    checks.push({ name: "rubric_version", pass: r.actual_rubric === r.expect_rubric, expected: r.expect_rubric, actual: r.actual_rubric });
  }
  checks.push({ name: "tenant_echoed", pass: r.tenant_id === "acme", expected: "acme", actual: r.tenant_id });
  const failed = checks.filter(function (c) { return !c.pass; });
  return { case_id: r.case_id, note: r.note, passed: failed.length === 0, checks: checks, latency_ms: r.latency_ms };
